    {
      "keystrokes": "python3 -c \"\nlines = open('vm.js').readlines()\n# Find the progress reporting section and add PC logging\nfor i,l in enumerate(lines):\n    if 'Progress:' in l:\n        lines[i] = \"      process.stderr.write(`[vm] Progress: ${icount} instructions, ${frameCount} frames, pc=0x${pc.toString(16)}, ${(icount / (elapsed / 1000)).toFixed(0)} ips\\\\n`);\\n\"\n        break\nopen('vm.js','w').writelines(lines)\nprint('added pc logging')\n\"\n",
      "duration": 0.1
    },
    {
      "keystrokes": "timeout 20 node vm.js 2>&1 | head -80\n",
      "duration": 15.0
    }
  ]
